const REFERENCE='https://manscod.github.io/other/sm64/';
export function installReferencePlayer(ctx){
 const panel=document.createElement('dialog');panel.className='sm64-reference';panel.setAttribute('aria-label','Super Mario 64 community web port');
 panel.innerHTML=`<header><div><small>COMMUNITY WEB PORT · EXTERNAL GAME</small><strong>Super Mario 64</strong></div><button data-full>Fullscreen</button><button data-close aria-label="Close Super Mario 64 and return to Super Mario 65">Back to Mario 65 ×</button></header><div class="reference-stage"></div><footer><p>Move: arrows · Jump: X · Attack: C · Crouch: Space · Start: Enter · Camera: WASD</p><p data-status role="status">Loading the community player…</p><div><button data-retry>Reload player</button><a href="${REFERENCE}" target="_blank" rel="noopener noreferrer">Open original page ↗</a></div><small>Hosted by manscod. This is an embedded third-party port, separate from Princewill’s original Super Mario 65 project. Its assets and source remain with their respective owners.</small></footer>`;
 document.body.append(panel);let timer,opener;
 const slot=panel.querySelector('.reference-stage'),status=panel.querySelector('[data-status]');
 function load(){clearTimeout(timer);slot.replaceChildren();const frame=document.createElement('iframe');frame.title='Super Mario 64 — manscod community web port';frame.src=REFERENCE;frame.allow='fullscreen; gamepad; autoplay';frame.allowFullscreen=true;frame.referrerPolicy='no-referrer';frame.addEventListener('load',()=>{status.textContent='Click inside the game, then press Enter. If it stays blank, use Open original page.';frame.focus()});frame.addEventListener('error',()=>{status.textContent='The external player could not load. Try Open original page.'});slot.append(frame);status.textContent='Loading the community player…';timer=setTimeout(()=>{status.textContent='This external game may take a moment. If it stays blank, open the original page.'},20000)}
 function open(e){opener=e.currentTarget;if(ctx.playing)document.querySelector('#pause-button').click();panel.showModal();document.body.classList.add('reference-open');load();panel.querySelector('[data-close]').focus()}
 function close(){clearTimeout(timer);slot.replaceChildren();document.body.classList.remove('reference-open');if(document.fullscreenElement===panel)document.exitFullscreen?.().catch(()=>{});opener?.focus()}
 panel.querySelector('[data-close]').onclick=()=>panel.close();panel.addEventListener('close',close);panel.addEventListener('keydown',e=>e.stopPropagation());panel.querySelector('[data-retry]').onclick=load;
 panel.querySelector('[data-full]').onclick=()=>{panel.requestFullscreen?.().catch(()=>{status.textContent='Fullscreen is unavailable. The player still fits this window.'})};
 const nav=document.createElement('button');nav.textContent='Play SM64';nav.onclick=open;document.querySelector('.game-header nav').prepend(nav);
 const card=document.createElement('div');card.className='sm64-launch';card.innerHTML='<span><strong>Also play Super Mario 64</strong><small>The community web port you shared, in its own player.</small></span><button>Open SM64 →</button>';card.querySelector('button').onclick=open;document.querySelector('.panel-actions').after(card);
}
